-- =====================================================================
-- SIGIAM-CC · Esquema de base de datos (PostgreSQL 17)
-- Conversión del script original para MySQL (docs/sigiam_general.sql).
--
-- Cambios respecto a MySQL:
--   * Se omiten DROP/CREATE DATABASE y USE: la base "sigiam_cc" la crea
--     el contenedor de Docker con la variable POSTGRES_DB.
--   * INT AUTO_INCREMENT  ->  INT GENERATED BY DEFAULT AS IDENTITY
--     ("BY DEFAULT" permite insertar ids explícitos, como hace el seed).
--   * ENUM(...)           ->  VARCHAR + CHECK (col IN (...)).
--
-- Docker ejecuta este archivo automáticamente (orden alfabético) la
-- primera vez que se crea el volumen de datos.
-- =====================================================================

-- ---------------------------------------------------------------------
-- CATÁLOGOS
-- ---------------------------------------------------------------------

-- Clases de equipo: Restaurador, UTR, Radio, Switch, Medidor, Banco de baterías...
CREATE TABLE tipo_equipo (
    id_tipo       INT           GENERATED BY DEFAULT AS IDENTITY,
    nombre_tipo   VARCHAR(60)   NOT NULL,
    descripcion   VARCHAR(150)  NULL,
    CONSTRAINT pk_tipo_equipo PRIMARY KEY (id_tipo),
    CONSTRAINT uq_tipo_nombre UNIQUE (nombre_tipo)
);

-- Fabricantes de los equipos
CREATE TABLE marca (
    id_marca      INT           GENERATED BY DEFAULT AS IDENTITY,
    nombre_marca  VARCHAR(60)   NOT NULL,
    CONSTRAINT pk_marca PRIMARY KEY (id_marca),
    CONSTRAINT uq_marca_nombre UNIQUE (nombre_marca)
);

-- Dónde está instalado el equipo
CREATE TABLE ubicacion (
    id_ubicacion  INT           GENERATED BY DEFAULT AS IDENTITY,
    subestacion   VARCHAR(80)   NOT NULL,
    circuito      VARCHAR(20)   NOT NULL,
    zona          VARCHAR(40)   NOT NULL,
    municipio     VARCHAR(60)   NOT NULL,
    CONSTRAINT pk_ubicacion PRIMARY KEY (id_ubicacion),
    CONSTRAINT uq_ubicacion UNIQUE (subestacion, circuito)
);

-- Situación actual: En funcionamiento, Con falla, En mantenimiento, Fuera de servicio
CREATE TABLE estado_operativo (
    id_estado     INT           GENERATED BY DEFAULT AS IDENTITY,
    nombre_estado VARCHAR(40)   NOT NULL,
    CONSTRAINT pk_estado_operativo PRIMARY KEY (id_estado),
    CONSTRAINT uq_estado_nombre UNIQUE (nombre_estado)
);

-- Personal que realiza los mantenimientos (RPE = registro de personal CFE)
CREATE TABLE trabajador (
    id_trabajador INT           GENERATED BY DEFAULT AS IDENTITY,
    rpe           VARCHAR(10)   NOT NULL,
    nombre        VARCHAR(100)  NOT NULL,
    puesto        VARCHAR(60)   NULL,
    CONSTRAINT pk_trabajador PRIMARY KEY (id_trabajador),
    CONSTRAINT uq_trabajador_rpe UNIQUE (rpe)
);

-- ---------------------------------------------------------------------
-- TABLAS OPERATIVAS
-- ---------------------------------------------------------------------

-- Inventario: cada activo físico del departamento
CREATE TABLE equipo (
    id_equipo         INT          GENERATED BY DEFAULT AS IDENTITY,
    num_serie         VARCHAR(40)  NOT NULL,
    num_economico     VARCHAR(20)  NOT NULL,
    modelo            VARCHAR(60)  NULL,
    id_tipo           INT          NOT NULL,
    id_marca          INT          NOT NULL,
    id_ubicacion      INT          NOT NULL,
    id_estado         INT          NOT NULL,
    fecha_instalacion DATE         NULL,
    CONSTRAINT pk_equipo PRIMARY KEY (id_equipo),
    CONSTRAINT uq_equipo_serie     UNIQUE (num_serie),
    CONSTRAINT uq_equipo_economico UNIQUE (num_economico),
    CONSTRAINT fk_equipo_tipo      FOREIGN KEY (id_tipo)      REFERENCES tipo_equipo (id_tipo),
    CONSTRAINT fk_equipo_marca     FOREIGN KEY (id_marca)     REFERENCES marca (id_marca),
    CONSTRAINT fk_equipo_ubicacion FOREIGN KEY (id_ubicacion) REFERENCES ubicacion (id_ubicacion),
    CONSTRAINT fk_equipo_estado    FOREIGN KEY (id_estado)    REFERENCES estado_operativo (id_estado)
);

-- Historial: cada intervención (preventiva o correctiva) hecha a un equipo
CREATE TABLE mantenimiento (
    id_mantenimiento     INT          GENERATED BY DEFAULT AS IDENTITY,
    id_equipo            INT          NOT NULL,
    id_trabajador        INT          NOT NULL,
    tipo_mantenimiento   VARCHAR(12)  NOT NULL,
    fecha_programada     DATE         NOT NULL,
    fecha_realizada      DATE         NULL,          -- NULL mientras esté pendiente
    estatus              VARCHAR(10)  NOT NULL DEFAULT 'Pendiente',
    condicion_encontrada VARCHAR(10)  NULL,
    observaciones        TEXT         NULL,
    CONSTRAINT pk_mantenimiento PRIMARY KEY (id_mantenimiento),
    CONSTRAINT fk_mant_equipo     FOREIGN KEY (id_equipo)     REFERENCES equipo (id_equipo),
    CONSTRAINT fk_mant_trabajador FOREIGN KEY (id_trabajador) REFERENCES trabajador (id_trabajador),
    -- Sustitutos de los ENUM de MySQL
    CONSTRAINT chk_mant_tipo      CHECK (tipo_mantenimiento IN ('Preventivo', 'Correctivo')),
    CONSTRAINT chk_mant_estatus_v CHECK (estatus IN ('Realizado', 'Pendiente')),
    CONSTRAINT chk_mant_condicion CHECK (condicion_encontrada IS NULL OR condicion_encontrada IN ('Buena', 'Regular', 'Mala')),
    -- Reglas de negocio del script original
    CONSTRAINT chk_mant_fechas  CHECK (fecha_realizada IS NULL OR fecha_realizada >= fecha_programada),
    CONSTRAINT chk_mant_estatus CHECK (
        (estatus = 'Realizado' AND fecha_realizada IS NOT NULL) OR
        (estatus = 'Pendiente' AND fecha_realizada IS NULL)
    )
);

-- ---------------------------------------------------------------------
-- ÍNDICES (aceleran los filtros y agrupaciones del dashboard)
-- ---------------------------------------------------------------------
CREATE INDEX idx_equipo_tipo      ON equipo (id_tipo);
CREATE INDEX idx_equipo_marca     ON equipo (id_marca);
CREATE INDEX idx_equipo_ubicacion ON equipo (id_ubicacion);
CREATE INDEX idx_equipo_estado    ON equipo (id_estado);
CREATE INDEX idx_mant_equipo      ON mantenimiento (id_equipo);
CREATE INDEX idx_mant_trabajador  ON mantenimiento (id_trabajador);
CREATE INDEX idx_mant_fecha       ON mantenimiento (fecha_programada);
CREATE INDEX idx_mant_estatus     ON mantenimiento (estatus);
